"""ProtocolLedger training job for Kaggle (generated by scripts/kaggle.py; do not edit).

Clones the repository at a pinned commit, rebuilds the cleaned splits from the pinned
corpus (every step verifies against the committed manifests), then trains each
requested configuration on the GPU. Outputs go to /kaggle/working/out.
"""

import json
import os
import subprocess
import sys
import time
from pathlib import Path

JOB = json.loads(r"""__JOB_JSON__""")
REPO = Path("/tmp/protocolledger")
OUT = Path("/kaggle/working/out")


def sh(cmd: str, cwd: Path | None = None, env: dict[str, str] | None = None) -> None:
    print(f"+ {cmd}", flush=True)
    subprocess.run(cmd, shell=True, check=True, cwd=cwd, env=env)


def main() -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    sh(f"git clone --quiet {JOB['repo']} {REPO}")
    sh(f"git checkout --quiet {JOB['commit']}", cwd=REPO)
    env = {
        **os.environ,
        "PYTHONPATH": str(REPO / "src"),
        "TOKENIZERS_PARALLELISM": "false",
    }
    probe = (
        "import sys, torch, transformers; "
        "print('python', sys.version.split()[0], 'torch', torch.__version__, "
        "'transformers', transformers.__version__, 'gpu', "
        "torch.cuda.get_device_name(0) if torch.cuda.is_available() else None)"
    )
    sh(f'{sys.executable} -c "{probe}"', env=env)
    for step in ("acquire", "convert", "build_splits"):
        sh(f"{sys.executable} scripts/{step}.py", cwd=REPO, env=env)

    results = []
    for config, seed in JOB["runs"]:
        name = f"{Path(config).stem}-s{seed}"
        started = time.time()
        try:
            sh(
                f"{sys.executable} scripts/train_neural.py {config} --seed {seed} --no-mlflow "
                f"--out {OUT / 'runs'} --reports {OUT / 'reports'}",
                cwd=REPO,
                env=env,
            )
            status = "ok"
        except subprocess.CalledProcessError as exc:
            status = f"failed (exit {exc.returncode})"
        last = OUT / "runs" / name / "last.pt"
        if status == "ok" and last.exists():
            last.unlink()  # resume state is only needed while a run is in progress
        results.append(
            {"run": name, "status": status, "minutes": round((time.time() - started) / 60, 1)}
        )
        (OUT / "job_status.json").write_text(json.dumps({"job": JOB, "results": results}, indent=1))
    if any(r["status"] != "ok" for r in results):
        sys.exit(1)


main()
